import{_ as t,o as e,c as r,a0 as o}from"./chunks/framework.DqMqoJl9.js";const C=JSON.parse('{"title":"String.fromCharCode()","description":"","frontmatter":{},"headers":[],"relativePath":"jsApi/String/fromCharCode.md","filePath":"jsApi/String/fromCharCode.md","lastUpdated":1791573371000}'),n={name:"jsApi/String/fromCharCode.md"};function l(s,a,i,d,p,c){return e(),r("div",null,[...a[0]||(a[0]=[o('<p><a href="https://developer.mozilla.org/zh-CN/docs/Web/JavaScript/Reference/Global_Objects/String/fromCharCode" target="_blank">原文链接</a><a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/String/fromCharCode" target="_blank">en</a></p><h1 id="string-fromcharcode" tabindex="-1">String.fromCharCode() <a class="header-anchor" href="#string-fromcharcode" aria-label="Permalink to &quot;String.fromCharCode()&quot;">​</a></h1><p>静态 String.fromCharCode() 方法返回使用指定的Unicode值序列创建的字符串。</p><h2 id="语法" tabindex="-1">语法 <a class="header-anchor" href="#语法" aria-label="Permalink to &quot;语法&quot;">​</a></h2><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">String.</span><span style="color:#6F42C1;">fromCharCode</span><span style="color:#24292E;">(num1, </span><span style="color:#D73A49;">...</span><span style="color:#24292E;">, numN)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="参数" tabindex="-1">参数 <a class="header-anchor" href="#参数" aria-label="Permalink to &quot;参数&quot;">​</a></h3><p><code>num1, ..., numN</code> 一组序列数字，表示 Unicode 值。</p><h2 id="描述" tabindex="-1">描述 <a class="header-anchor" href="#描述" aria-label="Permalink to &quot;描述&quot;">​</a></h2><p>该方法返回一个字符串，而不是一个 String 对象。</p><p>由于 fromCharCode 是 String 的静态方法，所以应该像这样使用：String.fromCharCode()，而不是作为你创建的 String 对象的方法。</p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="例子-使用-fromcharcode" tabindex="-1">例子：使用 fromCharCode <a class="header-anchor" href="#例子-使用-fromcharcode" aria-label="Permalink to &quot;例子：使用 fromCharCode&quot;">​</a></h3><p>下例返回字符串 &quot;ABC&quot;：</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">String.</span><span style="color:#6F42C1;">fromCharCode</span><span style="color:#24292E;">(</span><span style="color:#005CC5;">65</span><span style="color:#24292E;">,</span><span style="color:#005CC5;">66</span><span style="color:#24292E;">,</span><span style="color:#005CC5;">67</span><span style="color:#24292E;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="作用于高位编码-higher-values" tabindex="-1">作用于高位编码（higher values） <a class="header-anchor" href="#作用于高位编码-higher-values" aria-label="Permalink to &quot;作用于高位编码（higher values）&quot;">​</a></h2><p>尽管绝大部分常用的 Unicode 值可以用一个 16-bit 数字表示（正如 JavaScript 标准化过程早期），并且对于绝大部分值 fromCharCode() 返回一个字符（即对于绝大部分字符 UCS-2 值是 UTF-16 的子集），但是为了处理所有的 Unicode 值（至 21 bits），只用 fromCharCode() 是不足的。由于高位编码字符是用两个低位编码（lower value）表示形成的一个字符，因此String.fromCodePoint() （ES6 草案的一部分） 被用来返回这样一对低位编码，从而可以完全表示这些高位编码字符。</p><h2 id="规范" tabindex="-1">规范 <a class="header-anchor" href="#规范" aria-label="Permalink to &quot;规范&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Specification</th><th style="text-align:left;">Status</th><th style="text-align:left;">Comment</th></tr></thead><tbody><tr><td style="text-align:left;">ECMAScript 1rd Edition (ECMA-262)</td><td style="text-align:left;">Standard</td><td style="text-align:left;">Initial definition</td></tr><tr><td style="text-align:left;">ECMAScript 5.1 (ECMA-262)</td><td style="text-align:left;">Standard</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;">ECMAScript 2015 (6th Edition, ECMA-262)</td><td style="text-align:left;">Standard</td><td style="text-align:left;"></td></tr></tbody></table>',18)])])}const f=t(n,[["render",l]]);export{C as __pageData,f as default};
